      const recordStreamError = (streamName: 'stdout' | 'stderr') => (err: unknown): void => {
        if (streamName === 'stderr') stderrBroken = true;
        else stdoutBroken = true;
        if (asyncStreamError === null) {
          const message = err instanceof Error ? err.message : String(err);
          asyncStreamError = `host_run passthrough ${streamName} stream error: ${message}`;
        }
      };
      const onStdoutError = recordStreamError('stdout');
      const onStderrError = recordStreamError('stderr');

      // F-024: outstanding-write accounting for the live passthrough AND the final
      // diagnostics, WITHOUT serializing throughput. Every write below is issued as
      // write(text, cb) and is NOT awaited per-chunk; the callback decrements a
      // shared pending counter. drainPending() — awaited by the finally BEFORE the
      // error listeners are removed — resolves once every in-flight write has
      // settled, so a late EPIPE from the FINAL chunk(s) fires while our named
      // 'error' listeners are still attached. This closes the residual window that
      // F-020/F-023 left on fire-and-forget live passthrough writes.
      let pendingWrites = 0;
      let onDrained: (() => void) | null = null;
      const settleWrite = (): void => {
        pendingWrites -= 1;
        if (pendingWrites <= 0) {
          pendingWrites = 0;
          if (onDrained) {
            const notify = onDrained;
            onDrained = null;
            notify();
          }
        }
      };
      // Defensive cap: a genuinely WEDGED stream (a write that neither flushes nor
      // errors) must never hang host_run. On timeout we mark both streams broken and
      // proceed with listener removal; the ONLY regression is that, for such a
      // pathologically wedged stream, we revert to the pre-fix crash window (a
      // post-removal EPIPE could still be unhandled). Every real closed/broken pipe
      // settles its write callback (with or without error) well within this cap, so
      // in practice drainPending resolves as soon as the last chunk's EPIPE lands.
      const DRAIN_CAP_MS = 2000;
      const drainPending = (): Promise<void> => {
        if (pendingWrites <= 0) return Promise.resolve();
        return new Promise<void>((resolve) => {
          let settled = false;
          const timer = setTimeout(() => {
            if (settled) return;
            settled = true;
            onDrained = null;
            stdoutBroken = true;
            stderrBroken = true;
            resolve();
          }, DRAIN_CAP_MS);
          if (typeof timer.unref === 'function') timer.unref();
          onDrained = () => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve();
          };
        });
      };

      // F-006 / F-008 / F-020 / F-024: live passthrough. text mode routes host
      // stdout->stdout / stderr->stderr; json mode routes EVERYTHING to stderr so
      // stdout stays clean for the JSON result. Each chunk write is settle-aware
      // (write + counted callback) but NOT awaited, so throughput is never
      // serialized. A SYNCHRONOUS write failure is still thrown through to the CORE
      // guard (F-008: delivery stops, the run still completes, passthroughError
      // surfaces); an ASYNCHRONOUS 'error' recorded via the callback/listener flips
      // asyncStreamError so the NEXT chunk throws through instead of hammering a dead
      // pipe (F-020).
      const passthrough: HostRunPassthrough = (chunk: HostRunChunk) => {
        if (asyncStreamError !== null) {
          // The stream already emitted an async 'error' — the pipe is gone. Throw
          // through (the same contract as a sync write failure) so the core flips
          // its passthrough-broken flag instead of writing to a broken stream.
          throw new Error(asyncStreamError);
        }
        const toStderr = json || chunk.stream === 'stderr';
        const streamName: 'stdout' | 'stderr' = toStderr ? 'stderr' : 'stdout';
        // Skip a stream already known broken (honest degradation; passthroughError
        // already records the failure) — never queue a fresh write onto a dead pipe.
        if (toStderr ? stderrBroken : stdoutBroken) return;
        const stream = toStderr ? process.stderr : process.stdout;
        pendingWrites += 1;
        try {
          stream.write(chunk.text, (err) => {
            if (err) recordStreamError(streamName)(err);
            settleWrite();
          });
        } catch (err) {
          // Rare synchronous throw (e.g. write-after-end): settle the counter, then
          // throw through so the core flips its passthrough-broken flag (F-008).
          settleWrite();
          throw err instanceof Error ? err : new Error(`host_run passthrough write failed: ${String(err)}`);
        }
      };

      // F-020 / F-023 / F-024: gated, SETTLE-AWARE stderr diagnostics that also join
      // the pendingWrites accounting. Never write to a stderr already known broken
      // (avoids a late async EPIPE 'error' firing with no listener). When we DO
      // write, the promise resolves on the write CALLBACK and the SAME callback
      // decrements the shared counter — so both the per-call await (F-023) AND the
      // unified drainPending() (F-024) cover this write. The crux F-023 case is a
      // quiet text-mode run whose stderr is already closed, where this final usage
      // line is the FIRST stderr write (stderrBroken never opened, nothing skipped
      // it). A callback/synchronous error folds into the SAME broken/async-error
      // state (recordStreamError via onStderrError) and is swallowed — best-effort
      // diagnostics must never turn a completed run into a crash (F-008 contract).
      const emitStderr = (text: string): Promise<void> => {
        if (stderrBroken) return Promise.resolve();
        return new Promise<void>((resolve) => {
          pendingWrites += 1;
          try {
            process.stderr.write(text, (err) => {
              if (err) onStderrError(err);
              settleWrite();
              resolve();
            });
          } catch (err) {
            // Rare synchronous throw — flip broken state and settle.
            onStderrError(err);
            settleWrite();
            resolve();
          }
        });
      };

      // F-020: attach the async stream-error guards for the DURATION of the run,
      // then remove exactly them in the finally below (never removeAllListeners).
      process.stdout.on('error', onStdoutError);
      process.stderr.on('error', onStderrError);
      let result: HostRunResult;
      try {
        let run = submitted;
        let afterSequence = 0;
        let managedPassthroughError: string | null = null;
        const deliverNewFrames = (): void => {
          let hasMore = true;
          while (hasMore) {
            const output = readManagedHostRunOutput({ root: ctx.root, runId: submitted.runId, afterSequence });
            afterSequence = output.nextSequence;
            hasMore = output.hasMore;
            for (const frame of output.frames) {
              if (managedPassthroughError) break;
              try {
                passthrough({ stream: frame.stream, text: frame.text });
              } catch (error) {
                managedPassthroughError = error instanceof Error ? error.message : String(error);
              }
            }
            if (managedPassthroughError) break;
          }
        };
        while (!run.terminal) {
          deliverNewFrames();
          const status = await getManagedHostRunStatus({
            root: ctx.root,
            runId: submitted.runId,
            afterGeneration: run.generation,
            waitMs: 30_000,
          });
          run = status.run;
        }
        deliverNewFrames();
        result = readManagedHostRunResult(ctx.root, submitted.runId) ?? syntheticManagedResult(run);
        if (!result.passthroughError && managedPassthroughError) result.passthroughError = managedPassthroughError;

        // F-020: an async stream 'error' that landed AFTER the final chunk (so the
        // sink's throw-through never ran) is still surfaced honestly here — merge
        // the handler-observed async failure with the core-reported sink failure.
        const passthroughError = result.passthroughError ?? asyncStreamError;


        const usageLine = formatUsageLine(result);

        // F-008 / F-020: honest degradation notice — the run completed, but live
        // output delivery broke partway (text mode prints it; json mode carries the
        // field).
        const passthroughWarning = passthroughError
          ? `host_run warning: live output passthrough failed (${passthroughError}); output delivery degraded but the run and usage recording completed\n`
          : null;

        if (json) {
          // Machine mode: the full host transcript already streamed to stderr; the
          // JSON payload (exitCode, usage, refusal, bounded stdout tail) is the
          // single stdout line. The engine prints it; exitCode is a field.
          // F-023: await the write so it settles (and any EPIPE 'error' fires)
          // while our stderr listener is still attached (finally removes it).
          await emitStderr(`${usageLine}\n`);
          return {
            schemaVersion: 'lattice.host_run.v1',
            host: result.host,
            storyId: result.storyId,
            phase: result.phase,
            agentType: result.agentType,
            spawned: result.spawned,
            blocked: result.blocked,
            refusalReason: result.refusalReason,
            liveRuns: result.liveRuns,
            exitCode: result.exitCode,
            timedOut: result.timedOut,
            stdout: result.stdout,
            stderr: result.stderr,
            usage: result.usageSummary,
            passthroughError,
            runId: submitted.runId,
            managed: true,
          };
        }

        // Text mode. Host output already streamed live through the passthrough, so
        // the handler never re-prints it (no double-print). F-023: await every
        // diagnostic write so it settles while our stderr listener is still
        // attached (finally removes it) — the crux case is this quiet-run usage
        // line being the FIRST stderr write onto an already-closed stderr.
        if (passthroughWarning) await emitStderr(passthroughWarning);
        if (result.blocked || result.exitCode !== 0 || result.timedOut) {
          // Failure / refusal: usage/refusal line to stderr, then throw so the
          // process exits nonzero (engine forces exit 0 on a normal return).
          await emitStderr(`${usageLine}\n`);
          if (result.blocked) {
            throw new Error(`host_run refused (${result.refusalReason}); no host was launched`);
          }
          const timeoutNote = result.timedOut ? ' (timed out)' : '';
          throw new Error(`host_run: ${result.host} exited ${result.exitCode}${timeoutNote}`);
        }

        // Success: output already streamed; nothing left to print. F-023: await
        // the final usage-line write so a late EPIPE fires under our listener.
        await emitStderr(`${usageLine}\n`);
        return '';
      } finally {
        // F-024: await all in-flight passthrough + diagnostic writes (bounded by the
        // defensive DRAIN_CAP_MS) BEFORE removing the error listeners, so a late
        // EPIPE from the FINAL chunk(s) fires while our named 'error' listeners are
        // still attached. Resolves immediately when nothing is pending.
        await drainPending();
        // F-020: listener hygiene — remove exactly our two listeners, leaving any
        // other listeners on these shared streams untouched.
        process.stdout.removeListener('error', onStdoutError);
        process.stderr.removeListener('error', onStderrError);
      }
    },

    async host_run_status(args: HostRunStatusCommandArgs) {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_status: --runId is required');
      const status = await getManagedHostRunStatus({
        root: ctx.root,
        runId,
        afterGeneration: typeof args.afterGeneration === 'number' ? args.afterGeneration : undefined,
        waitMs: typeof args.waitMs === 'number' ? args.waitMs : undefined,
        maxWaitMs: options.statusWaitCapMs,
      });
      const output = readManagedHostRunOutput({
        root: ctx.root,
        runId,
        afterSequence: typeof args.afterSequence === 'number' ? args.afterSequence : 0,
      });
      if (wantsJson(args)) return { ...status, output };
      const terminal = status.run.terminal
        ? ` terminal=${status.run.terminal.state}:${status.run.terminal.reason}`
        : '';
      const receipt = status.receipt ? ` receiptId=${status.receipt.receiptId}` : '';
      return `${status.run.runId} state=${status.run.state} generation=${status.run.generation} deadlineAt=${status.run.deadlineAt} workerHeartbeatAt=${status.run.workerHeartbeatAt ?? 'none'} providerProgressMode=${status.run.providerProgressMode} lastProviderProgressAt=${status.run.lastProviderProgressAt ?? 'none'} replacementSafe=${status.run.replacementSafe}${terminal}${receipt}`;
    },

    async host_run_cancel(args: HostRunCancelCommandArgs) {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_cancel: --runId is required');
      const run = await cancelManagedHostRun({
        root: ctx.root,
        runId,
        reason: normalizeString(args.reason) || undefined,
      });
      if (wantsJson(args)) return { schemaVersion: 'lattice.host_run_cancel.v1', run };
      return `${run.runId} state=${run.state} cancelRequestedAt=${run.cancelRequestedAt ?? 'none'} replacementSafe=${run.replacementSafe}`;
    },

    async host_run_worker(args: HostRunWorkerCommandArgs): Promise<string> {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_worker: --runId is required');
      await runManagedHostRunWorker({ root: ctx.root, runId });
      return '';
    },
  };
}
  return authorized;
}

export interface CreateCrossHostReviewHandlersOptions {
  /** Injectable Codex process seam so the smoke can pass a fake (no real CLI). */
  codexRunner?: CodexReviewRunner;
  managedRunner?: HostRunRunner;
  launchWorker?: ManagedHostRunWorkerLauncher;
  /** Internal smoke seam for adversarial git-race coverage; never exposed through the CLI. */
  afterHeadCaptured?: () => void | Promise<void>;
  /** Internal smoke seam for final write-window race coverage; never exposed through the CLI. */
  beforeVerdictRecord?: () => void | Promise<void>;
  /** Internal smoke seam for post-write cleanup coverage; never exposed through the CLI. */
  afterVerdictPairWritten?: () => void | Promise<void>;
}

async function runManagedCodexReview(
  ctx: HandlerContext,
  opts: {
    storyId: string;
    phase: string;
    storyWorktree: string;
    prompt: string;
    timeoutMs: number;
    environment: NodeJS.ProcessEnv;
    managedRunId?: string;
    detach?: boolean;
  },
  options: CreateCrossHostReviewHandlersOptions,
): Promise<CodexReviewRunnerResult & { managedRunId: string; managedReceiptId: string }> {
  const injectedOutcome: { value: CodexReviewRunnerResult | null } = { value: null };
  const managedRunner: HostRunRunner | undefined = options.managedRunner ?? (options.codexRunner
    ? async plan => {
      const outcome = await options.codexRunner!({
        prompt: plan.stdinText ?? '',
        storyWorktree: opts.storyWorktree,
        timeoutMs: opts.timeoutMs,
        env: opts.environment,
      });
      injectedOutcome.value = outcome;
      if (outcome.stdout) plan.onChunk?.({ stream: 'stdout', text: outcome.stdout });
      return {
        stdout: outcome.stdout,
        stderr: '',
        exitCode: outcome.exitCode ?? 1,
        timedOut: outcome.timedOut,
        timeoutKind: outcome.timedOut ? 'total_timeout' : null,
        terminalReason: outcome.timedOut ? 'total_timeout' : outcome.exitCode === 0 ? 'completed' : 'exit_nonzero',
      };
    }
    : undefined);
  const injectedLauncher: ManagedHostRunWorkerLauncher | undefined = managedRunner
    ? async request => {
      void runManagedHostRunWorker(request, { runner: managedRunner, env: process.env });
      return { pid: process.pid };
    }
    : undefined;
  let submitted;
  if (opts.managedRunId) {
    const binding = readManagedHostRunBinding(ctx.root, opts.managedRunId);
    const expectedPromptDigest = `sha256:${createHash('sha256').update(opts.prompt, 'utf8').digest('hex')}`;
    if (
      binding.host !== 'codex'
      || binding.storyId !== opts.storyId
      || binding.phase !== opts.phase
      || binding.agentType !== 'cross-host-review:codex'
      || binding.profile !== 'cross_host_review_codex'
      || binding.cwd !== opts.storyWorktree
      || binding.projectRootHash !== projectRootHashFor(ctx.root)
      || binding.promptDigest !== expectedPromptDigest
      || binding.timeoutMs > opts.timeoutMs
    ) {
      throw new Error('cross_host_review: managedRunId binding does not match the current story/policy/snapshot/prompt; refusing to resume or spawn a replacement');
    }
    submitted = (await getManagedHostRunStatus({ root: ctx.root, runId: opts.managedRunId })).run;
  } else {
    submitted = await submitManagedHostRun({
      root: ctx.root,
      cwd: opts.storyWorktree,
      host: 'codex',
      storyId: opts.storyId,
      phase: opts.phase,
      agentType: 'cross-host-review:codex',
      promptText: opts.prompt,
      timeoutMs: opts.timeoutMs,
      deadlineMs: opts.timeoutMs,
      projectRootHash: projectRootHashFor(ctx.root),
      profile: 'cross_host_review_codex',
      environment: opts.environment,
    }, { launchWorker: options.launchWorker ?? injectedLauncher });
    ctx.store.appendProcessEvent(opts.storyId, {
      type: 'cross_host_review_managed_submitted',
      storyId: opts.storyId,
      managedRunId: submitted.runId,
      deadlineAt: submitted.deadlineAt,
      timestamp: new Date().toISOString(),
    });
    if (opts.detach) {
      throw new CrossHostReviewDetached({
        schemaVersion: 'lattice.cross_host_review_managed_submission.v1',
        storyId: opts.storyId,
        managedRunId: submitted.runId,
        state: submitted.state,
        deadlineAt: submitted.deadlineAt,
      });
    }
  }
  let run = submitted;
  while (!run.terminal) {
    const status = await getManagedHostRunStatus({
      root: ctx.root,
      runId: run.runId,
      afterGeneration: run.generation,
      waitMs: 30_000,
    });
    run = status.run;
  }
  const stdoutChunks: string[] = [];
  let afterSequence = 0;
  let outputTruncated = false;
  let hasMore = true;
  while (hasMore) {
    const output = readManagedHostRunOutput({ root: ctx.root, runId: run.runId, afterSequence });
    afterSequence = output.nextSequence;
    hasMore = output.hasMore;
    outputTruncated ||= output.truncated;
    for (const frame of output.frames) {
      if (frame.stream === 'stdout') stdoutChunks.push(frame.text);
    }
  }
  const rawStdout = stdoutChunks.join('');
  const maxBytes = 8 * 1024 * 1024;
  const stdout = rawStdout.slice(0, maxBytes);
  const result = readManagedHostRunResult(ctx.root, run.runId);
  const receipt = managedHostRunReceipt(ctx.root, run.runId);
  return {
    stdout,
    stdoutDigest: injectedOutcome.value?.stdoutDigest ?? createHash('sha256').update(rawStdout, 'utf8').digest('hex'),
    exitCode: result?.exitCode ?? (run.state === 'completed' ? 0 : run.state === 'timed_out' ? 124 : null),
    timedOut: run.state === 'timed_out' || result?.timedOut === true,
    truncated: injectedOutcome.value?.truncated === true || outputTruncated || rawStdout.length > maxBytes,
    managedRunId: run.runId,
    managedReceiptId: receipt.receiptId,
  };
}

interface CrossHostVerdictDraft {
  storyId: string;
  runId: string;
  hostId: string;
  provider: 'claude' | 'codex';
  sessionId: string;
  keyId: string;
  decision: VerdictDecision;
  materialDigest: string;
  storyFilesHash: string;
  validationDigest: string;
  promptDigest: string;
  receiptId?: string;
  note: string;
}

function buildLocalHostVerdict(draft: CrossHostVerdictDraft, issuedAt: string): HostVerdict {
  const base = {
    schemaVersion: 'lattice.host_verdict.v1' as const,
    mode: 'local' as const,
    storyId: draft.storyId,
    runId: draft.runId,
    hostId: draft.hostId,
    provider: draft.provider,
    sessionId: draft.sessionId,
export function createCrossHostReviewHandlers(
  ctx: HandlerContext,
  options: CreateCrossHostReviewHandlersOptions = {},
) {
  return {
    async cross_host_review(args: CrossHostReviewArgs): Promise<CrossHostReviewResult | CrossHostReviewManagedSubmission | string> {
      const storyId = normalizeString(args.storyId);
      if (!storyId) throw new Error('cross_host_review: storyId is required');
      if (!isCanonicalStoryId(storyId)) {
        throw new Error(`cross_host_review: storyId "${storyId}" is not a canonical, path-safe Proofbound story id`);
      }

      const workspace = resolveStoryCommandWorkspace(ctx.store, storyId, ctx.root);
      const projectRoot = workspace.signedWorkspaceRoot;
      const metadataRoot = workspace.metadataRoot || ctx.root;
      const gitCwd = resolveGitCwd({
        store: ctx.store,
        storyId,
        metadataRoot,
        projectRoot,
        cwd: projectRoot,
      });

      const headHash = currentGitHead(gitCwd);
      if (!headHash) {
        throw new Error('cross_host_review: cannot resolve current HEAD; refusing to record verdicts without a committed-tree binding');
      }
      await options.afterHeadCaptured?.();

      const materialDigest = currentMaterialHash(gitCwd, headHash, metadataRoot);
      if (!materialDigest) {
        throw new Error(`cross_host_review: cannot compute materialHash for captured HEAD ${headHash}; refusing to record verdicts with an empty materialDigest`);
      }
      const storyFilesHash = currentStoryFilesHash(gitCwd, headHash, metadataRoot);
      if (!storyFilesHash) {
        throw new Error(`cross_host_review: cannot compute storyFilesHash for captured HEAD ${headHash}; refusing to record verdicts without the story-owned file hash`);
      }

      // F-004: authorize + load the review-only dispatch policy BEFORE anything
      // spawns. Fail-closed: on a missing / unauthorized / non-review-granting
      // policy this throws and NO codex subprocess is ever started, and no verdict
      // is recorded.
      const reviewPolicy = authorizeReviewPolicy(metadataRoot, args.policy);

      const hostAFindings: Finding[] = args.hostAFindingsFile
        ? loadHostAFindings(normalizeString(args.hostAFindingsFile))
        : [];

      // F-004: the effective runtime bound is the SMALLER of the caller-requested
      // timeout and the policy's maxRuntimeMinutes ceiling — the policy can only
      // TIGHTEN, never widen, the bound.
      const requestedMinutes = typeof args.timeoutMinutes === 'number' && args.timeoutMinutes > 0
        ? args.timeoutMinutes
        : DEFAULT_TIMEOUT_MINUTES;
      // Bug10: the ceiling is trusted to be a real positive number here ONLY because
      // authorizeReviewPolicy already fail-closed-verified it (and checkDispatchPolicy
      // refused a malformed record upstream). We therefore use it DIRECTLY — no silent
      // `? ceiling : requestedMinutes` fallback that would let a non-number widen the
      // bound to the caller timeout. Re-assert as a final invariant to fail closed
      // rather than spawn without an enforced ceiling.
      // Bug10: the ceiling is trusted to be a real positive number here ONLY because
      // authorizeReviewPolicy already fail-closed-verified it (and checkDispatchPolicy
      // refused a malformed record upstream). We therefore use it DIRECTLY — no silent
      // `? ceiling : requestedMinutes` fallback that would let a non-number widen the
      // bound to the caller timeout. Re-assert as a final invariant to fail closed
      // rather than spawn without an enforced ceiling.
      const policyMaxMinutes = reviewPolicy.maxRuntimeMinutes;
      if (typeof policyMaxMinutes !== 'number' || !Number.isFinite(policyMaxMinutes) || policyMaxMinutes <= 0) {
        throw new Error(
          `cross_host_review: authorized policy "${reviewPolicy.policy}" yielded a non-numeric maxRuntimeMinutes ceiling `
          + `(${JSON.stringify(policyMaxMinutes)}); refusing to spawn the codex review subprocess without a valid runtime bound (fail-closed).`,
        );
      }
      const timeoutMinutes = Math.min(requestedMinutes, policyMaxMinutes);

      // F-004: the codex subprocess only sees a redacted env honoring the policy's
      // allowlist/denylist (and never operator secrets).
      const redactedEnv = buildRedactedEnv(process.env, reviewPolicy);

      const runId = normalizeString(args.runId) || `${storyId}-xhr-r1`;
      // Independent host identities (distinct hostId/sessionId/keyId) so the two
      // verdicts never collapse in groupByIndependentHost (verdicts.ts). F-011:
      // validate this BEFORE any Codex spawn or verdict record, so a caller cannot
      // manufacture an "independent" joint pass from the same host identity.
      const hostAId = normalizeString(args.hostA) || 'claude-host-a';
      const hostBId = normalizeString(args.hostB) || 'codex-host-b';
      const hostAIdentity: CrossHostIdentity = {
        hostId: hostAId,
        provider: 'claude',
        sessionId: derivedSession(storyId, hostAId),
        keyId: derivedKey(storyId, hostAId),
      };
      const hostBIdentity: CrossHostIdentity = {
        hostId: hostBId,
        provider: 'codex',
        sessionId: derivedSession(storyId, hostBId),
        keyId: derivedKey(storyId, hostBId),
      };
      assertHostIndependence(hostAIdentity, hostBIdentity);

      // Integrity preflight (host-B escalation-lane fix): FAIL CLOSED before any
      // codex spawn if the worktree has uncommitted MATERIAL (source) drift versus
      // HEAD. The recorded verdict binds to the HEAD materialHash (the committed
      // tree), so Codex must review a clean HEAD snapshot and the live worktree
      // must still be source-clean before we record the verdict. `.lattice/`
      // metadata is excluded (Codex never reads story bookkeeping, and it churns
      // constantly).
      assertMaterialCleanForReview(gitCwd);
      assertReviewHeadStillCurrent(gitCwd, headHash);

      // F-010: Codex must not review the mutable story worktree after the clean
      // preflight. Give it an immutable detached snapshot of the captured HEAD
      // SHA instead, then
      // re-check the original worktree before recording. A concurrent source edit
      // or clean HEAD move after the snapshot cannot influence what Codex reviewed,
      // and we refuse to bind/record the verdict if either drift is still present.
      const requestedManagedRunId = normalizeString(args.managedRunId);
      const resumedBinding = requestedManagedRunId
        ? readManagedHostRunBinding(ctx.root, requestedManagedRunId)
        : null;
      if (resumedBinding && (!existsSync(resumedBinding.cwd) || resumedBinding.storyId !== storyId || resumedBinding.profile !== 'cross_host_review_codex')) {
        throw new Error('cross_host_review: managedRunId does not identify a resumable snapshot for this story');
      }
      const snapshot = resumedBinding
        ? { worktree: resumedBinding.cwd, cleanup: () => cleanupHeadReviewWorktree(gitCwd, resumedBinding.cwd) }
        : createCleanHeadReviewWorktree(gitCwd, headHash);
      let leaf: CodexReviewLeafResult;
      let managedRunId = '';
      let managedReceiptId = '';
      let preserveSnapshot = false;
      try {
        try {
          leaf = await runCodexReviewLeaf(
            {
              storyId,
              storyWorktree: snapshot.worktree,
              materialHash: materialDigest,
              hostAFindings,
              timeoutMs: timeoutMinutes * 60 * 1000,
              env: redactedEnv,
              managedExecution: true,
